import {firebaseConnection} from './firebase-config.js';
import {studioMarkup,initNarrationStudio} from './narration-studio.js';
import {initGoogleAuth} from './google-auth.js';

export async function initCafe(api){
 const {state,$,get,put,database,persistDoc,renderLibrary,openDocument,currentIndex,jump,buildBook,toast,escapeHTML:esc,paginateText,saveImported}=api;
 if(!state.db)return;state.home=true;
 document.body.dataset.view='home';
 initGoogleAuth();
 const iconPaths={book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1m0-15c3-2 6-2 9-1v15c-3-1-6-1-9 1V5Z',file:'M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 12h8M8 16h6',shelf:'M4 4v16M9 4v16M14 4v16M18 5l3 14M2 21h20',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8',play:'m8 4 12 8-12 8V4Z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'M4 12h16m-6-6 6 6-6 6',menu:'M4 6h16M4 12h16M4 18h16'};
 document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[el.dataset.icon]||iconPaths.book}"/></svg>`;});
 $('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');};
 $('#quick-import').onclick=$('#nav-import').onclick=()=>$('#file-input').click();
 $('#hero-search-form').onsubmit=e=>{e.preventDefault();const query=$('#hero-search').value;navigate('shelf');$('#search').value=query;$('#search').dispatchEvent(new Event('input'));$('#search').focus();};
 const narrationStudio=initNarrationStudio(api);
 let view='home',adminTab='overview',collectionTab='quotes',selection=null,speechToken=0,recorder=null,recordingTimer=null,micStream=null,recordPending=false,recordSaving=false;
 let playbackURLs=[];
 const read=async(id,fallback)=>{const r=await get('settings',id);return r?.value??fallback;};
 let collections=await read('collections',[]),recordings=await read('recordings',[]),jobs=await read('production-jobs',[]),preferences=await read('reading-preferences',{theme:'light',brightness:94,paper:'warm',language:'ko'});
 const save=(id,value)=>put('settings',{id,value});
 const date=timestamp=>new Date(timestamp).toLocaleDateString('ko-KR',{month:'short',day:'numeric'});
 const names={home:'라운지',shelf:'내 서재',collections:'문장과 책갈피',recordings:'나의 목소리',profile:'마이페이지',admin:'운영 대시보드'};
 const stories=[
  ['morning','고요한 아침의 문장들','아침은 작은 소리로 시작되었다. 창문 너머에서 이름 모를 새가 울었고, 식탁 위의 빈 잔에는 햇빛이 먼저 담겼다. 나는 물이 끓기를 기다리며 어제 접어 둔 페이지를 펼쳤다.\n\n책 속의 풍경은 밤새 조금도 달라지지 않았다. 그런데 그 풍경을 바라보는 마음은 어제와 달랐다. 바쁜 날에는 지나쳤던 문장 하나가 오늘은 오래 눈에 남았다.\n\n서두르지 않아도 되는 일이 있다는 것. 끝까지 가지 않아도 충분히 아름다운 길이 있다는 것. 그런 생각을 하며 나는 첫 모금을 마셨다.\n\n창가에 작은 화분을 옮겨 놓았다. 잎 하나가 빛을 향해 기울었다. 누구에게도 설명하지 않은 채, 각자의 방향으로 자라는 것들이 있었다.\n\n오늘 해야 할 일은 여전히 많았다. 하지만 모든 일을 한꺼번에 시작할 필요는 없었다. 한 문장, 한 모금, 한 번의 숨. 아침은 그만큼의 자리를 내어 주었다.\n\n나는 책갈피를 조금 뒤로 옮겼다. 아주 멀리 가지 않았어도 괜찮았다. 오늘의 나는 어제보다 한 페이지 더, 나만의 속도를 알아 가고 있었다.'],
  ['window','창가에 머무는 시간','오후의 카페에는 자리가 하나 남아 있었다. 가장 안쪽, 창문과 작은 책장 사이였다. 나는 외투를 벗어 의자에 걸고 오래 읽지 않은 책을 꺼냈다.\n\n유리 밖에서는 사람들이 저마다의 방향으로 걸었다. 우산을 든 사람, 꽃을 안은 사람, 빈손으로 하늘을 올려다보는 사람. 이곳에서 보니 모두 한 권의 이야기처럼 보였다.\n\n커피가 식는 동안 책장을 두 번 넘겼다. 그 사이 구름이 움직였고, 탁자에 드리운 그림자가 조금 짧아졌다. 아무 일도 일어나지 않은 시간에도 세상은 조용히 다음 장으로 가고 있었다.\n\n나는 공책에 한 줄을 적었다. 머무는 일도 때로는 앞으로 가는 방법이라고. 오래 고민하지 않고 쓴 말이었지만, 이상하게도 마음 한쪽이 편안해졌다.\n\n돌아갈 시간이 되었을 때 책에는 아직 읽지 않은 페이지가 많았다. 나는 그것을 숙제라고 부르지 않기로 했다. 다시 이 창가를 찾을 이유라고 부르기로 했다.'],
  ['forest','숲이 건네는 작은 인사','길은 낮은 언덕 뒤로 사라졌다. 지도를 접자 나뭇잎 부딪치는 소리가 가까워졌다. 나는 목적지를 잠시 잊고 발밑의 흙을 바라보았다.\n\n숲에는 빠른 발걸음도 느린 발걸음도 있었다. 개미는 나무뿌리를 돌아갔고, 바람은 높은 가지를 먼저 지나갔다. 누구도 다른 이에게 속도를 맞추라고 말하지 않았다.\n\n쓰러진 나무 위에서 작은 풀들이 자라고 있었다. 끝났다고 생각한 자리에 시작이 모여 있었다. 오래된 나무는 더는 하늘을 향해 자라지 않았지만, 여러 생명의 작은 땅이 되어 주었다.\n\n나는 그 옆에 앉아 물을 마셨다. 대단한 깨달음은 없었다. 다만 어깨에 힘을 조금 빼도 될 것 같았다. 멀리서 새 한 마리가 울었고, 나는 그것을 인사로 받아들이기로 했다.\n\n돌아오는 길은 올 때와 같은 길이었다. 그런데 나무 사이로 보이는 하늘이 조금 더 넓었다. 변한 것은 길이 아니라 고개를 드는 마음이었는지도 모른다.'],
  ['moon','달빛 아래 한 페이지','집 안의 불을 하나씩 끄고 작은 스탠드만 남겼다. 책상 가장자리에 빛의 원이 생겼다. 오늘 하루가 조용히 그 원 밖으로 물러났다.\n\n낮에는 쉽게 읽히지 않던 글이 밤에는 다르게 다가왔다. 문장 사이의 빈자리에도 누군가의 망설임과 다정함이 숨어 있었다. 나는 빨리 이해하려는 마음을 내려놓았다.\n\n창문에 비친 얼굴이 조금 피곤해 보였다. 오늘 충분히 잘했는지 묻는 대신, 오늘 무엇이 좋았는지 떠올렸다. 잘 익은 과일, 길에서 마주친 고양이, 늦지 않게 도착한 안부.\n\n작은 것들을 세다 보니 하루가 생각보다 넉넉했다. 나쁜 순간만 크게 기억하던 마음이 조용해졌다. 좋은 일들도 제자리를 찾을 시간이 필요했던 것이다.\n\n마지막 문장을 소리 내어 읽었다. 방 안에 내 목소리가 잠깐 머물렀다. 언젠가 오늘을 잊더라도 이 목소리의 온도는 기억하고 싶었다.\n\n책을 덮자 창밖에서 달이 보였다. 다음 이야기는 내일 읽어도 괜찮았다. 오늘은 여기까지. 그것만으로도 충분한 밤이었다.']
 ];
 if(!await read('cafe-seeded',false)){
  for(let i=0;i<stories.length;i++){const [slug,title,text]=stories[i];const content=title+'\n폴리오 창작 단편\n\n'+text;const file=new Blob([content],{type:'text/plain;charset=utf-8'});const doc={id:'folio-'+slug,title,author:'Folio 오리지널',type:'text',editorial:true,size:file.size,pages:paginateText(content).length,created:Date.now()-i*1000,current:0,lastRead:0,favorite:false,coverAsset:'./assets/cover-'+slug+'.svg',publication:'published',rightsReviewed:true,rightsNote:'이 프로젝트에서 새로 작성한 창작 단편',source:'Folio original',language:'ko'};if(!state.docs.some(d=>d.id===doc.id)){await saveImported(doc,file);state.docs.push(doc);}}
  await save('cafe-seeded',true);renderLibrary();
 }
 function applyPreferences(){document.body.classList.toggle('night',preferences.theme==='dark');$('#theme-toggle').textContent=preferences.theme==='dark'?'☼':'☾';$('#theme-toggle').setAttribute('aria-label',preferences.theme==='dark'?'라이트 모드 전환':'다크 모드 전환');document.documentElement.style.setProperty('--brightness',preferences.brightness/100);$('#brightness').value=preferences.brightness;$('#paper-theme').value=preferences.paper;$('#reader-stage').classList.remove('paper-warm','paper-light','paper-dark');$('#reader-stage').classList.add('paper-'+preferences.paper);$('#language').value=preferences.language;}
 applyPreferences();
 async function setPreference(key,value){preferences[key]=value;applyPreferences();try{await save('reading-preferences',preferences);}catch{toast('설정을 저장하지 못했습니다.');}}
 $('#theme-toggle').onclick=()=>setPreference('theme',preferences.theme==='dark'?'light':'dark');
 $('#brightness').oninput=e=>setPreference('brightness',Number(e.target.value));
 $('#paper-theme').onchange=e=>setPreference('paper',e.target.value);
 const english={home:'Lounge',library:'My library',collections:'Quotes & bookmarks',recordings:'My voice',profile:'My page',admin:'Admin dashboard'};
 const korean={home:'라운지',library:'내 서재',collections:'문장과 책갈피',recordings:'나의 목소리',profile:'마이페이지',admin:'운영 대시보드'};
 function translateNav(){for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=(preferences.language==='en'?english:korean)[el.dataset.i18n];document.documentElement.lang=preferences.language;}
 translateNav();$('#language').onchange=e=>{setPreference('language',e.target.value);translateNav();toast(e.target.value==='en'?'English navigation preview. Full translation is planned.':'한국어 메뉴로 전환했습니다.');};
 function selectFilter(filter){state.filter=filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));renderLibrary();}
 function title(kicker,heading,description){return `<div class="feature-title"><div class="eyebrow">${kicker}</div><h1>${heading}</h1><p>${description}</p></div>`;}
 function stats(){return `<div class="stats">${[['서재의 책',state.docs.length,'나만의 작은 도서관'],['읽고 있는 책',state.docs.filter(d=>d.lastRead).length,'조금씩 쌓이는 시간'],['간직한 문장',collections.filter(x=>x.kind==='quote').length,'다시 만나고 싶은 말'],['목소리 기록',recordings.length,'나의 낭독 아카이브']].map(([label,n,note])=>`<div class="stat"><small>${label}</small><strong>${n}<span> ${['목소리 기록','간직한 문장'].includes(label)?'개':'권'}</span></strong><span>${note}</span></div>`).join('')}</div>`;}
 function revokePlayback(){playbackURLs.forEach(URL.revokeObjectURL);playbackURLs=[];}
 function navigate(next){view=next;state.home=next==='home';if(next==='home'){state.query='';$('#search').value='';$('#hero-search').value='';}document.body.dataset.view=next;document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','메뉴 열기');revokePlayback();$('#location-title').textContent=names[next];$('#home-hero').hidden=next!=='home';$('#quick-paths').hidden=next!=='home';$('#library-content').hidden=!['home','shelf'].includes(next);$('#feature-panel').hidden=['home','shelf'].includes(next);document.querySelectorAll('.sidebar [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next));if(next==='home'||next==='shelf'){selectFilter('all');}else renderFeature();window.scrollTo({top:0,behavior:'smooth'});}
 document.addEventListener('click',e=>{const nav=e.target.closest('button[data-view],a[data-view]');if(nav)navigate(nav.dataset.view);});
 function firstBook(){return [...state.docs].sort((a,b)=>(b.lastRead||0)-(a.lastRead||0)||b.created-a.created)[0];}
 $('#hero-read').onclick=()=>{const d=firstBook();if(d)openDocument(d.id);else $('#file-input').click();};
 $('#quick-listen').onclick=async()=>{const d=firstBook();if(d){await openDocument(d.id);$('#listen-page').click();}};
 function collectionMarkup(){const items=collections.filter(x=>x.kind===(collectionTab==='quotes'?'quote':'bookmark'));return title('WORDS WORTH KEEPING','마음에 남은 페이지','책갈피는 읽던 자리를, 발췌는 마음에 남은 문장을 기억합니다.')+`<div class="shelf-tabs"><button data-collection-tab="quotes" class="${collectionTab==='quotes'?'active':''}">발췌 문장 ${collections.filter(x=>x.kind==='quote').length}</button><button data-collection-tab="bookmarks" class="${collectionTab==='bookmarks'?'active':''}">페이지 책갈피 ${collections.filter(x=>x.kind==='bookmark').length}</button></div><div class="collection-list">${items.map(x=>`<article class="quote-card"><small>${date(x.created)} · ${x.page+1}쪽</small><blockquote>${x.kind==='quote'?esc(x.text):'♧ '+esc(x.title)}</blockquote><small>${esc(x.title)}</small><footer><button data-entry-open="${x.id}">책에서 다시 보기 ↗</button><button data-entry-delete="${x.id}">삭제</button></footer></article>`).join('')}</div>${items.length?'':'<div class="empty-note">아직 간직한 기록이 없어요.<br>책을 펼쳐 책갈피를 누르거나, 문장 선택을 켜고 드래그해 보세요.</div>'}`;}
 async function recordingsMarkup(){const markup=title('STORIES IN YOUR OWN VOICE','내 목소리로 남긴 이야기','책을 펼치고 녹음을 눌러 보세요. 녹음은 이 브라우저에 보관되며 파일로 내려받을 수 있습니다.')+`<div class="collection-list" id="recording-list"></div>${recordings.length?'':'<div class="empty-note">첫 번째 낭독을 기다리고 있어요.<br>내 서재에서 책을 열고 ● 녹음을 눌러 시작하세요.<br>한 번에 최대 10분까지 녹음할 수 있습니다.</div>'}`;$('#feature-panel').innerHTML=markup;for(const r of recordings){const file=await get('files',r.id);if(view!=='recordings')return;if(!file)continue;const url=URL.createObjectURL(file.blob);playbackURLs.push(url);$('#recording-list').insertAdjacentHTML('beforeend',`<article class="quote-card"><small>${date(r.created)} · ${r.page+1}쪽 · ${Math.ceil(r.duration)}초</small><h3>${esc(r.title)}</h3><audio controls preload="metadata" src="${url}"></audio><footer><a href="${url}" download="${esc(r.title)}.${r.mime.includes('mp4')?'m4a':'webm'}">녹음 다운로드 ↓</a><button data-record-delete="${r.id}">삭제</button></footer></article>`);}}
 function profileMarkup(){return title('YOUR READING JOURNEY','오늘도, 한 장의 나를 만나다.','읽고, 모으고, 다시 펼치는 모든 순간을 한곳에.')+`<section class="panel account-panel"><div><h2>나의 계정</h2><p>Google 계정으로 로그인하고 계정을 관리하세요.</p></div><button class="secondary" data-account-open>Google 계정 로그인 · 관리</button></section>`+stats()+`<section class="panel"><h2>나의 서재</h2><div class="inline-actions"><button data-profile-filter="recent">읽고 있는 책 ${state.docs.filter(d=>d.lastRead).length} ↗</button><button data-profile-filter="favorite">찜한 책 ${state.docs.filter(d=>d.favorite).length} ↗</button><button data-profile-filter="uploads">내가 올린 책 ${state.docs.filter(d=>d.type!=='demo'&&!d.editorial).length} ↗</button><button data-view="collections">문장과 책갈피 ${collections.length} ↗</button><button data-view="recordings">녹음 ${recordings.length} ↗</button></div></section><section class="panel"><h2>이어서 읽기</h2>${state.docs.filter(d=>d.lastRead).sort((a,b)=>b.lastRead-a.lastRead).slice(0,5).map(d=>`<div class="resume-row"><button data-resume="${d.id}">${esc(d.title)} <span>${d.current+1} / ${d.pages}쪽 →</span></button></div>`).join('')||'<p>책을 펼치면 마지막으로 읽은 위치를 여기에 기억해 둘게요.</p>'}</section><section class="panel"><h2>내 기록 보관하기</h2><div class="inline-actions"><button data-view="admin">운영 대시보드 미리보기 ↗</button></div><p>현재는 이 브라우저의 로컬 서재입니다. 다른 기기와 동기화되지 않으며 브라우저 데이터 삭제 시 기록도 지워집니다. 원본 책과 녹음은 따로 보관해 주세요.</p><div class="inline-actions"><button id="export-notes">발췌 · 책갈피 내보내기 ↓</button></div></section>`;}
 function adminMarkup(){const heads={overview:'운영 현황',books:'도서 · 원고 관리',queue:'AI 제작 대기열',rights:'사용자 · 권한'};return title('FOLIO STUDIO / ADMIN','이야기를 준비하는 공간','도서를 정리하고, 제작 상태를 살피고, 다음 이야기를 준비합니다.')+`<div class="notice">로컬 운영 미리보기 · 실제 관리자 인증과 서버 저장소는 아직 연결되지 않았습니다. 이 화면의 변경은 현재 브라우저에만 저장됩니다. AI 생성·클라우드 발행은 잠겨 있습니다.</div><nav class="admin-tabs">${Object.entries(heads).map(([id,n])=>`<button data-admin-tab="${id}" class="${adminTab===id?'active':''}">${n}</button>`).join('')}</nav>`+(adminTab==='overview'?adminOverview():adminTab==='books'?adminBooks():adminTab==='queue'?adminQueue():adminRights());}
 function adminOverview(){const uploads=state.docs.filter(d=>!d.editorial&&d.type!=='demo');return `<div class="stats"><div class="stat"><small>등록된 도서</small><strong>${state.docs.length}</strong><span>현재 브라우저 기준</span></div><div class="stat"><small>업로드 원고</small><strong>${uploads.length}</strong><span>PDF · 이미지 · 텍스트</span></div><div class="stat"><small>제작 요청</small><strong>${jobs.length}</strong><span>실제 생성은 비활성화</span></div><div class="stat"><small>연결된 서비스</small><strong>0<span> / 3</span></strong><span>Vercel · Firebase · AI</span></div></div><section class="panel"><h2>콘텐츠 구성</h2><div class="admin-bars">${[['PDF',state.docs.filter(d=>d.type==='pdf').length],['텍스트',state.docs.filter(d=>d.type==='text').length],['이미지',state.docs.filter(d=>d.type==='image').length],['가이드',state.docs.filter(d=>d.type==='demo').length]].map(([name,count])=>`<div style="height:${Math.max(3,Math.min(100,count/state.docs.length*100))}%"><span>${name} · ${count}</span></div>`).join('')}</div></section><section class="panel"><h2>제작부터 서재까지</h2><p>원고 등록 → 원문·번역본 권리 검수 → 표지 준비 → 나레이션·문장 타임코드 → 검수 → 발행</p><div class="inline-actions"><button data-admin-tab="books">원고 관리 열기 ↗</button><button data-admin-tab="queue">제작 대기열 확인 ↗</button></div></section>`;}
 function adminBooks(){return `<section class="panel"><h2>도서 목록 <span>${state.docs.length}</span></h2><div class="inline-actions"><button id="admin-import">＋ 원고 가져오기</button></div><div class="table-wrap"><table><thead><tr><th>도서명</th><th>형식 / 분량</th><th>구분</th><th>권리 검수</th><th>관리</th></tr></thead><tbody>${state.docs.map(d=>`<tr><td>${esc(d.title)}<br><small>${esc(d.author||'개인 업로드')}</small></td><td>${d.type.toUpperCase()} · ${d.pages}쪽</td><td><span class="badge ${d.publication==='published'?'':'wait'}">${d.publication==='published'?'로컬 전시':d.type==='demo'?'가이드':'개인 서재'}</span></td><td>${d.rightsReviewed?'검수 기록 있음':'미검수'}</td><td><button data-edit-book="${d.id}">편집</button></td></tr>`).join('')}</tbody></table></div></section>`;}
 function adminQueue(){return studioMarkup(state.docs)+`<section class="panel"><h2>새 제작 요청</h2><p>관리자·제작 권한 사용자 전용 기능으로 연결할 예정입니다. 지금은 비용 승인 대기 목록만 저장하며 외부 API를 호출하지 않습니다.</p><form id="job-form"><div class="job-fields"><label>원고 <select name="book" required>${state.docs.map(d=>`<option value="${d.id}">${esc(d.title)}</option>`).join('')}</select></label><label>작업 <select name="kind"><option value="narration">나레이션 제작</option><option value="cover">표지 제작</option><option value="ocr">스캔 PDF 문자 인식</option></select></label><button class="secondary" type="submit">승인 대기 목록에 추가</button></div></form></section><section class="panel"><h2>제작 대기열</h2>${jobs.length?`<div class="table-wrap"><table><thead><tr><th>도서</th><th>작업</th><th>상태</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc(j.title)}</td><td>${{narration:'나레이션',cover:'표지',ocr:'OCR'}[j.kind]}</td><td><span class="badge wait">비용 승인 · 서비스 연결 대기</span></td><td><button data-job-delete="${j.id}">취소</button></td></tr>`).join('')}</tbody></table></div>`:'<p>아직 제작 요청이 없습니다.</p>'}<p>예약 실행, 재시도, 자동 과금은 모두 비활성 상태입니다.</p></section>`;}
 function adminRights(){return `<section class="panel"><h2>권한 설계</h2><p>실제 사용자 목록은 Firebase Authentication 연결 후 표시됩니다. 아래는 적용할 권한 정책이며, 로컬에서 역할을 변경해 서버 권한을 얻을 수 없습니다.</p><div class="table-wrap"><table><thead><tr><th>역할</th><th>개인 업로드 · 독서</th><th>나레이션 요청</th><th>발행 · 권한 부여</th></tr></thead><tbody><tr><td>일반 사용자</td><td>본인 자료만</td><td>불가</td><td>불가</td></tr><tr><td>제작 권한 사용자</td><td>본인 자료만</td><td>승인된 작업만</td><td>불가</td></tr><tr><td>편집자</td><td>검수 대상 도서</td><td>불가</td><td>검수만 가능</td></tr><tr><td>관리자</td><td>운영 범위</td><td>비용 승인된 작업만</td><td>가능</td></tr></tbody></table></div></section><section class="panel"><h2>연결 상태</h2><p>Firebase 프로젝트: ${esc(firebaseConnection.projectId)} · 설정 준비됨<br>Firebase 인증: Google 로그인 연결<br>Firestore · Storage: 미연결 · 비용 조건 확인 대기<br>Analytics: 비활성<br>Vercel 배포: GitHub 자동 배포<br>AI 생성 서비스: RunPod · 승인 전 실행 차단</p></section>`;}
 function renderFeature(){revokePlayback();if(view==='collections')$('#feature-panel').innerHTML=collectionMarkup();else if(view==='profile')$('#feature-panel').innerHTML=profileMarkup();else if(view==='admin')$('#feature-panel').innerHTML=adminMarkup();else if(view==='recordings')recordingsMarkup().catch(()=>toast('녹음을 불러오지 못했습니다.'));}
 window.addEventListener('folio:library',()=>{if(!['home','shelf'].includes(view))renderFeature();});
 $('#feature-panel').addEventListener('click',async e=>{try{const b=e.target.closest('button');if(!b)return;if(b.dataset.collectionTab){collectionTab=b.dataset.collectionTab;renderFeature();}if(b.dataset.adminTab){adminTab=b.dataset.adminTab;renderFeature();}if(b.dataset.profileFilter){navigate('shelf');selectFilter(b.dataset.profileFilter);}if(b.dataset.resume)await openDocument(b.dataset.resume);if(b.id==='admin-import')$('#file-input').click();if(b.dataset.editBook)editBook(b.dataset.editBook);if(b.dataset.entryOpen){const entry=collections.find(x=>x.id===b.dataset.entryOpen);if(!state.docs.some(d=>d.id===entry.bookId)){toast('원본 책이 서재에서 삭제되었습니다.');return;}await openDocument(entry.bookId);if(state.active)jump(entry.page);}if(b.dataset.entryDelete){const next=collections.filter(x=>x.id!==b.dataset.entryDelete);await save('collections',next);collections=next;renderFeature();}if(b.dataset.jobDelete){const next=jobs.filter(j=>j.id!==b.dataset.jobDelete);await save('production-jobs',next);jobs=next;renderFeature();}if(b.dataset.recordDelete){await deleteRecording(b.dataset.recordDelete);renderFeature();}if(b.id==='export-notes'){const blob=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),collections},null,2)],{type:'application/json'});download(blob,'folio-reading-notes.json');}}catch{toast('변경 내용을 저장하지 못했습니다. 저장 공간을 확인해 주세요.');}});
 $('#feature-panel').addEventListener('submit',async e=>{if(e.target.id!=='job-form')return;e.preventDefault();const data=new FormData(e.target),doc=state.docs.find(d=>d.id===data.get('book'));if(!doc)return;const job={id:crypto.randomUUID(),bookId:doc.id,title:doc.title,kind:data.get('kind'),status:'awaiting-approval',created:Date.now()};try{await save('production-jobs',[...jobs,job]);jobs.push(job);renderFeature();toast('승인 대기 목록에 저장했습니다. 생성 작업은 실행되지 않습니다.');}catch{toast('요청을 저장하지 못했습니다.');}});
 function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function editBook(id){const d=state.docs.find(x=>x.id===id);const dialog=document.createElement('dialog');dialog.className='editor-dialog';dialog.innerHTML=`<h2>도서 정보 편집</h2><form><label>제목<input name="title" value="${esc(d.title)}" maxlength="160" required></label><label>저자 · 제작자<input name="author" value="${esc(d.author||'')}" maxlength="100"></label><label>원문 출처<input name="source" value="${esc(d.source||'')}" maxlength="500" placeholder="원문 URL 또는 창작 출처"></label><label>권리 검수 메모<textarea name="rightsNote" rows="3" maxlength="2000">${esc(d.rightsNote||'')}</textarea></label><label class="check"><input name="reviewed" type="checkbox" ${d.rightsReviewed?'checked':''}> 원문·번역·표지의 사용 권리 검수 기록을 남겼습니다.</label><label>로컬 전시 상태<select name="publication"><option value="private" ${d.publication!=='published'?'selected':''}>개인 서재 / 검수 대기</option><option value="published" ${d.publication==='published'?'selected':''}>로컬 전시</option></select></label><p class="muted">온라인 공개나 클라우드 업로드는 실행되지 않습니다.</p><div class="dialog-actions"><button type="button" class="secondary" id="editor-cancel">취소</button><button class="primary" type="submit">저장</button></div></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('#editor-cancel').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),title=String(form.get('title')).trim(),reviewed=form.get('reviewed')==='on',source=String(form.get('source')).trim(),note=String(form.get('rightsNote')).trim();if(!title)return;if(form.get('publication')==='published'&&(!reviewed||!source||!note)){toast('전시 전에 출처, 권리 검수 메모, 검수 확인을 모두 입력해 주세요.');return;}const update={...d,title,author:String(form.get('author')).trim(),source,rightsNote:note,rightsReviewed:reviewed,publication:form.get('publication')};try{await put('documents',update);Object.assign(d,update);renderLibrary();dialog.close();toast('도서 정보를 이 브라우저에 저장했습니다.');}catch{toast('도서 정보를 저장하지 못했습니다.');}};}
 $('#reader-settings-toggle').onclick=()=>{const hidden=!$('#reading-settings').hidden;$('#reading-settings').hidden=hidden;$('#reader-settings-toggle').setAttribute('aria-expanded',String(!hidden));if(state.active)buildBook(currentIndex());};
 function markBookmark(){if(!state.active)return;const found=collections.some(x=>x.kind==='bookmark'&&x.bookId===state.active.id&&x.page===currentIndex());$('#bookmark-page').textContent=found?'♧ 책갈피 저장됨':'♧ 책갈피';$('#bookmark-page').setAttribute('aria-pressed',String(found));}
 $('#bookmark-page').onclick=async()=>{if(!state.active)return;const id=state.active.id,page=currentIndex(),existing=collections.find(x=>x.kind==='bookmark'&&x.bookId===id&&x.page===page);const next=existing?collections.filter(x=>x!==existing):[{id:crypto.randomUUID(),kind:'bookmark',bookId:id,title:state.active.title,page,created:Date.now()},...collections];try{await save('collections',next);collections=next;markBookmark();toast(existing?'책갈피를 해제했습니다.':'이 페이지를 책갈피에 저장했습니다.');}catch{toast('책갈피를 저장하지 못했습니다.');}};
 $('#select-mode').onclick=async()=>{if(!state.active)return;stopSpeech();state.selecting=!state.selecting;$('#select-mode').setAttribute('aria-pressed',String(state.selecting));$('#reader-stage').classList.toggle('selecting',state.selecting);buildBook(currentIndex());if(state.selecting&&['pdf','image'].includes(state.active.type))await showTranscript();else $('#transcript').hidden=true;toast(state.selecting?'문장을 드래그한 뒤 발췌에 저장을 눌러 주세요.':'책장 넘김 모드입니다.');};
 async function showTranscript(){const id=state.active?.id,page=currentIndex();$('#transcript').hidden=false;$('#transcript-body').textContent='텍스트를 준비하고 있습니다…';let text='';try{if(state.active?.type==='pdf'){const p=await state.pdf.getPage(page+1);const result=await p.getTextContent();text=result.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('');}if(!state.active||state.active.id!==id||currentIndex()!==page)return;$('#transcript-body').textContent=text.trim()||'이미지 기반 페이지입니다. 책처럼 보기는 가능하며, 문장 선택과 나레이션에는 OCR 처리가 필요합니다. OCR은 운영 대시보드에서 승인 대기 요청으로 등록할 수 있습니다.';$('#transcript-body').dataset.readable=text.trim()?'true':'false';}catch{$('#transcript-body').textContent='이 페이지의 텍스트를 추출하지 못했습니다.';$('#transcript-body').dataset.readable='false';}}
 $('#close-transcript').onclick=()=>$('#transcript').hidden=true;
 document.addEventListener('selectionchange',()=>{const sel=window.getSelection();const anchor=sel?.anchorNode?.parentElement,focus=sel?.focusNode?.parentElement;const text=sel?.toString().trim();if(!state.active||!text||!anchor||!focus||!anchor.closest('.page-content,#transcript-body')||!focus.closest('.page-content,#transcript-body')||anchor.closest('#transcript-body')?.dataset.readable==='false'){$('#save-selection').hidden=true;return;}selection={text:text.slice(0,10000),bookId:state.active.id,title:state.active.title,page:Number(anchor.closest('[data-page]')?.dataset.page??currentIndex())};$('#save-selection').hidden=false;});
 $('#save-selection').onpointerdown=e=>e.preventDefault();
 $('#save-selection').onclick=async()=>{if(!selection)return;const entry={...selection,id:crypto.randomUUID(),kind:'quote',created:Date.now()};try{await save('collections',[entry,...collections]);collections.unshift(entry);$('#save-selection').hidden=true;window.getSelection()?.removeAllRanges();selection=null;toast('문장과 책갈피의 발췌 목록에 저장했습니다.');}catch{toast('발췌를 저장하지 못했습니다.');}};
 function stopSpeech(){speechToken++;window.speechSynthesis?.cancel();document.querySelectorAll('.spoken-line').forEach(n=>n.classList.remove('spoken-line'));$('#listen-page').setAttribute('aria-pressed','false');$('#listen-page').textContent='▷ 듣기';}
 function lineElements(root){if(root.classList.contains('text-page')||root.id==='transcript-body'){const text=root.textContent;root.replaceChildren();text.split(/\n/).forEach(line=>{const span=document.createElement('span');span.className='text-line';span.textContent=line+'\n';root.append(span);});return [...root.querySelectorAll('.text-line')].filter(n=>n.textContent.trim());}return [...root.querySelectorAll('h2,p')];}
 $('#listen-page').onclick=async()=>{if(await narrationStudio.playSaved())return;if($('#listen-page').getAttribute('aria-pressed')==='true'){stopSpeech();return;}if(!state.active)return;if(recorder?.state==='recording'||recordPending){toast('녹음을 마친 뒤 듣기를 시작해 주세요.');return;}if(!window.speechSynthesis){toast('이 브라우저는 음성 읽기를 지원하지 않습니다.');return;}const voices=speechSynthesis.getVoices().filter(v=>v.localService);const lang=state.active.language||'ko';const voice=voices.find(v=>v.lang.toLowerCase().startsWith(lang));if(!voice){toast('이 기기에 해당 언어의 오프라인 음성이 없습니다. 운영체제 음성을 설치하면 무료로 미리 들을 수 있습니다.');return;}const bookId=state.active.id,page=currentIndex();let root=state.nodes[page]?.querySelector('.text-page,.demo-page');if(!root){await showTranscript();if(!state.active||state.active.id!==bookId||currentIndex()!==page||$('#transcript-body').dataset.readable!=='true')return;root=$('#transcript-body');}const lines=lineElements(root);if(!lines.length)return;const token=++speechToken;$('#listen-page').setAttribute('aria-pressed','true');$('#listen-page').textContent='Ⅱ 듣기 중지';let index=0;function next(){if(token!==speechToken||!state.active||state.active.id!==bookId)return;document.querySelectorAll('.spoken-line').forEach(n=>n.classList.remove('spoken-line'));if(index>=lines.length){stopSpeech();return;}const line=lines[index++];line.classList.add('spoken-line');const utterance=new SpeechSynthesisUtterance(line.textContent);utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=Number($('#voice-rate').value);utterance.onend=next;utterance.onerror=()=>{if(token===speechToken){stopSpeech();toast('음성 재생을 완료하지 못했습니다. 다시 시도해 주세요.');}};speechSynthesis.speak(utterance);}next();};
 async function deleteRecording(id){const next=recordings.filter(r=>r.id!==id);await new Promise((resolve,reject)=>{const tx=state.db.transaction(['files','settings'],'readwrite');tx.objectStore('files').delete(id);tx.objectStore('settings').put({id:'recordings',value:next});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});recordings=next;}
 function stopRecording(){if(recorder?.state==='recording')recorder.stop();clearTimeout(recordingTimer);micStream?.getTracks().forEach(t=>t.stop());micStream=null;$('#record-voice').setAttribute('aria-pressed','false');$('#record-voice').textContent='● 녹음';}
 $('#record-voice').onclick=async()=>{if(recordPending||recordSaving)return;if(recorder?.state==='recording'){stopRecording();return;}if(!state.active)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('이 브라우저에서는 녹음을 지원하지 않습니다. HTTPS 또는 localhost에서 최신 브라우저를 사용해 주세요.');return;}recordPending=true;const doc={id:state.active.id,title:state.active.title},page=currentIndex();try{stopSpeech();micStream=await navigator.mediaDevices.getUserMedia({audio:true});if(!state.active||state.active.id!==doc.id){micStream.getTracks().forEach(t=>t.stop());micStream=null;return;}const preferred=['audio/webm;codecs=opus','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));const activeRecorder=new MediaRecorder(micStream,preferred?{mimeType:preferred}:{});recorder=activeRecorder;const chunks=[],started=Date.now();activeRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};activeRecorder.onstop=async()=>{recordSaving=true;const blob=new Blob(chunks,{type:activeRecorder.mimeType});const meta={id:'recording-'+crypto.randomUUID(),bookId:doc.id,title:doc.title,page,created:started,duration:(Date.now()-started)/1000,mime:activeRecorder.mimeType};try{if(!blob.size){toast('녹음된 소리가 없습니다.');return;}const next=[meta,...recordings];await new Promise((resolve,reject)=>{const tx=state.db.transaction(['files','settings'],'readwrite');tx.objectStore('files').put({id:meta.id,blob});tx.objectStore('settings').put({id:'recordings',value:next});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});recordings=next;if(view==='recordings')renderFeature();toast('나의 목소리에 녹음을 저장했습니다.');}catch{download(blob,'folio-recording.'+(activeRecorder.mimeType.includes('mp4')?'m4a':'webm'));toast('서재 저장 실패로 녹음 파일을 다운로드했습니다.');}finally{recordSaving=false;recorder=null;}};activeRecorder.onerror=()=>{stopRecording();toast('녹음 장치 오류로 녹음을 중단했습니다.');};activeRecorder.start(1000);$('#record-voice').setAttribute('aria-pressed','true');$('#record-voice').textContent='■ 녹음 저장';recordingTimer=setTimeout(()=>{stopRecording();toast('10분 녹음을 마치고 저장합니다.');},600000);toast('녹음 중입니다. 다시 누르면 저장합니다.');}catch{micStream?.getTracks().forEach(t=>t.stop());micStream=null;toast('마이크 권한 또는 녹음 장치를 확인해 주세요.');}finally{recordPending=false;}};
 window.addEventListener('folio:page',()=>{stopSpeech();selection=null;$('#save-selection').hidden=true;queueMicrotask(()=>{markBookmark();if(state.selecting&&state.active?.type==='pdf')showTranscript();});});
 window.addEventListener('folio:close',()=>{stopSpeech();stopRecording();state.selecting=false;$('#select-mode').setAttribute('aria-pressed','false');$('#reader-stage').classList.remove('selecting');$('#transcript').hidden=true;$('#save-selection').hidden=true;selection=null;});
 window.addEventListener('beforeunload',e=>{if(recorder?.state==='recording'||recordPending||recordSaving){e.preventDefault();e.returnValue='';}});
 renderLibrary();
}
